const statusLabel=value=>({pending:'Pendiente',approved:'Aprobado',partial:'Aprobado parcialmente',justified:'Justificado',rejected:'Rechazado',accepted:'Aceptado',cancelled:'Cancelado',not_applicable:'No aplica',present:'Presente',absent:'Falta',incomplete:'Marcación incompleta',draft:'Borrador',preparing:'En preparación',closed:'Cerrada',paid:'Pagada',quincenal:'Quincenal',mensual:'Mensual',microempresa:'Planilla microempresa',recibo_honorarios:'Recibo por honorarios',first_half:'Primera quincena',second_half:'Segunda quincena',split:'50% en cada quincena'}[value]||value||'—');
