  const {error:ue}=await db.from('attendance').update({clock_in,clock_out,status:'present',late_minutes:late,early_leave_minutes:early,overtime_minutes:overtime,approved_overtime_minutes:0,overtime_review_status:overtime>=overtimeThreshold?'pending':'not_applicable',review_status:clean?'approved':'pending',admin_note:'Marcación completada por administración usando el horario programado.'}).eq('id',id);toast(ue?ue.message:'Marcación completada con el horario programado.',!!ue);if(!ue)attendance();
