  const totalIncome=Number(x.base_amount||0)+Number(x.overtime_amount||0)+Number(x.holiday_amount||0)+Number(x.bonuses||0),totalDiscount=Number(x.attendance_discount||0)+Number(x.manual_discount||0)+Number(x.pension_discount||0);
