function printPayslip(){const content=$('#payslip')?.outerHTML;if(!content)return;const w=window.open('','_blank','width=900,height=700');if(!w)return toast('Permite las ventanas emergentes para imprimir la boleta.',true);w.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Boleta BURBUPET</title><style>body{font:15px Arial,sans-serif;color:#073572;padding:32px;max-width:850px;margin:auto}h2{font-size:28px}.section-head,.payroll-net{display:flex;justify-content:space-between;align-items:center}.notice{padding:18px;background:#eef6fb;border-radius:12px;margin:18px 0;line-height:1.7}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #d8e1ea;text-align:left}th{background:#edf4fa}.payroll-net{margin-top:20px;padding:18px;background:#d8f1e9;border-radius:12px;font-size:22px}.badge{padding:8px 12px;background:#d9e9fa;border-radius:20px}.eyebrow{letter-spacing:2px;font-size:12px}.payslip-note{color:#65758b;margin-top:24px}@media print{body{padding:0}}</style></head><body>${content}</body></html>`);w.document.close();setTimeout(()=>w.print(),250)}
async function closePayrollPeriod(){const open=(state.payrollItems||[]).map(x=>x.payroll_periods).filter(x=>x?.status==='preparing').sort((a,b)=>b.end_date.localeCompare(a.end_date))[0];if(!open)return toast('No hay una planilla en preparación.',true);if(!confirm(`¿Cerrar la planilla del ${date(open.start_date)} al ${date(open.end_date)}? Después quedará protegida y lista para emitir boletas.`))return;const {error}=await db.from('payroll_periods').update({status:'closed',closed_at:new Date().toISOString(),closed_by:state.session.user.id}).eq('id',open.id);if(error)return toast(error.message,true);await notifyPayrollWorkers(open.id,'Boleta disponible',`Tu boleta del ${date(open.start_date)} al ${date(open.end_date)} ya está disponible.`,`payroll_closed_${open.id}`);toast('Planilla cerrada y trabajadores notificados.');payroll()}
async function markPayrollPaid(){const period=(state.payrollItems||[]).map(x=>x.payroll_periods).filter(x=>x?.status==='closed').sort((a,b)=>b.end_date.localeCompare(a.end_date))[0];if(!period)return toast('No hay una planilla cerrada pendiente de pago.',true);const paymentDate=prompt('Fecha efectiva del pago (AAAA-MM-DD):',todayLocal());if(!paymentDate)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(paymentDate))return toast('Ingresa la fecha en formato AAAA-MM-DD.',true);if(!confirm(`¿Confirmar como pagada la planilla del ${date(period.start_date)} al ${date(period.end_date)}?`))return;const {error}=await db.from('payroll_periods').update({status:'paid',payment_date:paymentDate}).eq('id',period.id);if(error)return toast(error.message,true);await notifyPayrollWorkers(period.id,'Pago confirmado',`Tu pago del periodo ${date(period.start_date)} al ${date(period.end_date)} fue registrado con fecha ${date(paymentDate)}.`,`payroll_paid_${period.id}`);toast('Pago confirmado y trabajadores notificados.');payroll()}

async function preparePayroll(){
  const cutoff=prompt('Fecha de cálculo (AAAA-MM-DD):',todayLocal());if(!cutoff)return;
  const d=new Date(cutoff+'T12:00:00'),year=d.getFullYear(),month=d.getMonth(),day=d.getDate(),monthText=`${year}-${String(month+1).padStart(2,'0')}`,start=`${monthText}-${day<=15?'01':'16'}`,end=day<=15?`${monthText}-15`:`${monthText}-${new Date(year,month+1,0).getDate()}`;
  await getWorkers();
  const {data:existing,error:lookupError}=await db.from('payroll_periods').select('*').eq('start_date',start).eq('end_date',end).eq('frequency','quincenal').maybeSingle();
  if(lookupError)return toast(lookupError.message,true);
  if(existing&&existing.status!=='preparing')return toast(`Esta planilla ya está ${statusLabel(existing.status).toLowerCase()} y está protegida contra nuevos cálculos.`,true);
  const periodResult=existing?{data:existing,error:null}:await db.from('payroll_periods').insert({start_date:start,end_date:end,payment_date:end,frequency:'quincenal',status:'preparing'}).select().single(),period=periodResult.data,pe=periodResult.error;
  if(pe)return toast(pe.message,true);
  const [{data:a},{data:previousItems},{data:settings}]=await Promise.all([db.from('attendance').select('*').gte('work_date',start).lte('work_date',cutoff),db.from('payroll_items').select('*').eq('period_id',period.id),db.from('company_settings').select('overtime_factor,overtime_factor_after_two_hours').eq('id',1).single()]);
  const previous=new Map((previousItems||[]).map(x=>[x.worker_id,x])),firstFactor=Number(settings?.overtime_factor||1.25),laterFactor=Number(settings?.overtime_factor_after_two_hours||1.35);
  const items=state.workers.filter(w=>w.active).map(w=>{
    const days=(a||[]).filter(x=>x.worker_id===w.id&&x.review_status!=='justified'),old=previous.get(w.id),base=w.payment_frequency==='quincenal'?w.base_salary/2:w.base_salary,pensionBaseMonthly=Number(w.pensionable_salary||0),timing=w.pension_deduction_timing||'split',isFirstHalf=day<=15,pension_base_amount=timing==='split'?pensionBaseMonthly/2:timing==='first_half'&&isFirstHalf||timing==='second_half'&&!isFirstHalf?pensionBaseMonthly:0,minute=w.base_salary/30/8/60,bonuses=Number(old?.bonuses||0),manual_discount=Number(old?.manual_discount||0);
    const attendance_discount=days.reduce((s,x)=>s+(x.status==='absent'?w.base_salary/30:(x.late_minutes+x.early_leave_minutes)*minute),0);
    const overtime_amount=days.reduce((s,x)=>{const m=x.approved_overtime_minutes||0;return s+Math.min(m,120)*minute*firstFactor+Math.max(0,m-120)*minute*laterFactor},0);
    const holiday_amount=days.reduce((s,x)=>s+(x.is_holiday&&x.status==='present'&&!x.holiday_rest_substituted?w.base_salary/30*2:0),0);
    const pension_discount=w.payment_type==='microempresa'?pension_base_amount*w.pension_rate/100:0;
    return{period_id:period.id,worker_id:w.id,base_amount:base,pension_base_amount,family_allowance:0,overtime_amount,holiday_amount,bonuses,manual_discount,adjustment_note:old?.adjustment_note||null,attendance_discount,pension_discount,discounts:attendance_discount+manual_discount+pension_discount,net_amount:base+overtime_amount+holiday_amount+bonuses-attendance_discount-manual_discount-pension_discount};
  });
  const {error}=await db.from('payroll_items').upsert(items,{onConflict:'period_id,worker_id'});
  toast(error?error.message:'Planilla preparada correctamente.',!!error);payroll();
}

async function registerHolidayWork(){
  await getWorkers();
  modal(`<h2>Registrar feriado trabajado</h2><form id="holiday-work" class="forms"><label class="full">Trabajador<select name="worker_id" required>${state.workers.filter(w=>w.active).map(w=>`<option value="${w.id}">${esc(w.full_name)}</option>`).join('')}</select></label><label>Fecha del feriado<input name="work_date" type="date" required></label><label>Descanso sustitutorio<select name="rest"><option value="no">No</option><option value="si">Sí</option></select></label><div class="notice full">Sin descanso sustitutorio se añadirá el equivalente a dos remuneraciones diarias. Con descanso sustitutorio no se genera pago adicional.</div><button class="full">Guardar feriado</button></form>`);
  $('#holiday-work').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),workerId=Number(f.get('worker_id')),workDate=f.get('work_date'),rest=f.get('rest')==='si';const {data:record,error:findError}=await db.from('attendance').select('id,status').eq('worker_id',workerId).eq('work_date',workDate).maybeSingle();if(findError)return toast(findError.message,true);if(!record)return toast('No existe una marcación para ese trabajador en la fecha indicada.',true);if(record.status!=='present')return toast('El feriado solo puede registrarse cuando existe una jornada trabajada.',true);const {error}=await db.from('attendance').update({is_holiday:true,holiday_rest_substituted:rest}).eq('id',record.id);if(error)return toast(error.message,true);$('#modal').remove();toast('Feriado registrado. Vuelve a preparar la planilla para actualizar el cálculo.');payroll()};
}

async function setVoluntaryBonus(id,current,net){
  const value=prompt('Monto de la bonificación extraordinaria voluntaria:',String(current||0));
  if(value===null)return;
  const amount=Number(value);
  if(!Number.isFinite(amount)||amount<0)return toast('Ingresa un monto válido.',true);
  const note=prompt('Motivo de la bonificación (decisión de la empresa):','Bonificación extraordinaria voluntaria')||'Bonificación extraordinaria voluntaria';
  const {error}=await db.from('payroll_items').update({bonuses:amount,adjustment_note:note,net_amount:Number(net)-Number(current||0)+amount}).eq('id',id);
  toast(error?error.message:'Bonificación voluntaria actualizada.',!!error);payroll();
}
