async function markAllNotificationsRead(){const {error}=await db.from('notifications').update({read_at:new Date().toISOString()}).eq('recipient_user_id',state.session.user.id).is('read_at',null);if(error)return toast(error.message,true);notifications();renderNav()}
function fitSheet(sheet,rows){const keys=Object.keys(rows[0]||{});sheet['!cols']=keys.map(k=>({wch:Math.min(36,Math.max(k.length+2,...rows.map(r=>String(r[k]??'').length+2)))}));sheet['!autofilter']={ref:sheet['!ref']}}
async function exportAttendanceExcel(){const month=state.attendanceMonth||todayLocal().slice(0,7),{data,error}=await db.from('attendance').select('*,workers(full_name,dni)').gte('work_date',month+'-01').lte('work_date',month+'-31').order('work_date');if(error)return toast(error.message,true);if(!data?.length)return toast('No hay asistencias para exportar en el mes elegido.',true);const rows=data.map(x=>({'Fecha':date(x.work_date),'Trabajador':x.workers?.full_name||'','DNI':x.workers?.dni||'','Entrada':String(x.clock_in||''),'Salida':String(x.clock_out||''),'Horario entrada':String(x.scheduled_start||''),'Horario salida':String(x.scheduled_end||''),'Tardanza (min)':Number(x.late_minutes||0),'Salida anticipada (min)':Number(x.early_leave_minutes||0),'Permanencia (min)':Number(x.overtime_minutes||0),'Extra aprobada (min)':Number(x.approved_overtime_minutes||0),'Asistencia':statusLabel(x.status),'Revisión':statusLabel(x.review_status),'Respuesta':x.worker_response||'','Nota administrativa':x.admin_note||''})),sheet=XLSX.utils.json_to_sheet(rows);fitSheet(sheet,rows);const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,sheet,'Asistencia');XLSX.writeFile(book,`BURBUPET_Asistencia_${month}.xlsx`);toast('Control mensual exportado correctamente.')}
async function exportPayrollExcel(){const latest=(state.payrollItems||[]).map(x=>x.payroll_periods).filter(Boolean).sort((a,b)=>b.end_date.localeCompare(a.end_date))[0];if(!latest)return toast('No hay una planilla para exportar.',true);const {data,error}=await db.from('payroll_items').select('*,workers(full_name,dni,job_title,area,base_salary,pension_system,pensionable_salary),payroll_periods(*)').eq('period_id',latest.id).order('worker_id');if(error)return toast(error.message,true);const rows=(data||[]).map(x=>({'Periodo inicio':date(x.payroll_periods.start_date),'Periodo fin':date(x.payroll_periods.end_date),'Fecha de pago':date(x.payroll_periods.payment_date),'Estado':statusLabel(x.payroll_periods.status),'Trabajador':x.workers?.full_name||'','DNI':x.workers?.dni||'','Cargo':x.workers?.job_title||'','Área':x.workers?.area||'','Sueldo mensual total':Number(x.workers?.base_salary||0),'Base del periodo':Number(x.base_amount||0),'Horas extra':Number(x.overtime_amount||0),'Feriados':Number(x.holiday_amount||0),'Bono voluntario':Number(x.bonuses||0),'Descuento asistencia':Number(x.attendance_discount||0),'Otros descuentos':Number(x.manual_discount||0),'Base pensionaria del periodo':Number(x.pension_base_amount||0),'Sistema pensionario':String(x.workers?.pension_system||'').toUpperCase(),'Descuento pensión':Number(x.pension_discount||0),'Neto a pagar':Number(x.net_amount||0)}));if(!rows.length)return toast('La planilla no tiene trabajadores para exportar.',true);const totals=rows.reduce((a,r)=>{a.base+=r['Base del periodo'];a.extras+=r['Horas extra'];a.feriados+=r.Feriados;a.bonos+=r['Bono voluntario'];a.descuentos+=r['Descuento asistencia']+r['Otros descuentos']+r['Descuento pensión'];a.neto+=r['Neto a pagar'];return a},{base:0,extras:0,feriados:0,bonos:0,descuentos:0,neto:0}),summaryRows=[['BURBUPET ERP - Resumen de planilla'],['Periodo',`${date(latest.start_date)} al ${date(latest.end_date)}`],['Estado',statusLabel(latest.status)],['Trabajadores',rows.length],['Base del periodo',totals.base],['Horas extra',totals.extras],['Feriados',totals.feriados],['Bonos voluntarios',totals.bonos],['Descuentos totales',totals.descuentos],['Neto total',totals.neto]],summary=XLSX.utils.aoa_to_sheet(summaryRows),detail=XLSX.utils.json_to_sheet(rows);summary['!cols']=[{wch:24},{wch:24}];fitSheet(detail,rows);const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,summary,'Resumen');XLSX.utils.book_append_sheet(book,detail,'Detalle');XLSX.writeFile(book,`BURBUPET_Planilla_${latest.start_date}_${latest.end_date}.xlsx`);toast('Planilla exportada correctamente.')}
async function settings(){if(state.profile.app_role!=='admin'){state.page='home';return loadPage()}const {data:s,error}=await db.from('company_settings').select('*').eq('id',1).single();if(error)throw error;$('#view').innerHTML=`<div class="settings-layout"><section class="card"><div class="section-head"><div><span class="eyebrow">MOTOR DE ASISTENCIA</span><h2>Reglas de cálculo</h2><p class="section-copy">Los cambios se aplicarán a las siguientes cargas del huellero.</p></div></div><form id="settings-form" class="forms"><label>Tolerancia de ingreso (minutos)<input name="late_tolerance" type="number" min="0" max="60" value="${Number(s.late_tolerance)}" required><small>Hasta este minuto no se genera tardanza.</small></label><label>Revisar permanencia desde (minutos)<input name="overtime_tolerance" type="number" min="1" max="240" value="${Number(s.overtime_tolerance)}" required><small>Desde este tiempo aparece para revisión.</small></label><label>Margen de salida (minutos)<input name="exit_grace_minutes" type="number" min="0" max="60" value="${Number(s.exit_grace_minutes)}" required><small>No genera incidencia dentro de este margen.</small></label><label>Remuneración mínima referencial<input name="minimum_wage" type="number" min="0" step="0.01" value="${Number(s.minimum_wage)}" required></label><label>Factor de las primeras 2 horas extra<input name="overtime_factor" type="number" min="1" max="5" step="0.01" value="${Number(s.overtime_factor)}" required><small>1.25 equivale a una sobretasa de 25%.</small></label><label>Factor desde la tercera hora extra<input name="overtime_factor_after_two_hours" type="number" min="1" max="5" step="0.01" value="${Number(s.overtime_factor_after_two_hours)}" required><small>1.35 equivale a una sobretasa de 35%.</small></label><div class="notice full"><b>Configuración vigente:</b> ingreso hasta ${Number(s.late_tolerance)} minutos sin tardanza; salida hasta ${Number(s.exit_grace_minutes)} minutos sin incidencia; permanencias desde ${Number(s.overtime_tolerance)} minutos pasan a revisión y solo se pagan después de ser aprobadas.</div><button class="full">Guardar configuración</button></form></section><aside class="card rules-summary"><span class="eyebrow">REGLAS PROTEGIDAS</span><h2>Cómo trabaja el motor</h2><ol><li>Las jornadas normales se aprueban automáticamente.</li><li>Las faltas y marcaciones incompletas requieren revisión.</li><li>Las permanencias nunca se pagan automáticamente.</li><li>Las planillas cerradas no pueden recalcularse.</li><li>Los cambios no modifican periodos ya cerrados.</li></ol></aside></div>`;$('#settings-form').onsubmit=saveSettings}
async function saveSettings(e){e.preventDefault();const f=new FormData(e.target),values={late_tolerance:Number(f.get('late_tolerance')),overtime_tolerance:Number(f.get('overtime_tolerance')),exit_grace_minutes:Number(f.get('exit_grace_minutes')),minimum_wage:Number(f.get('minimum_wage')),overtime_factor:Number(f.get('overtime_factor')),overtime_factor_after_two_hours:Number(f.get('overtime_factor_after_two_hours')),updated_at:new Date().toISOString()};if(values.overtime_tolerance<=values.exit_grace_minutes)return toast('La revisión de permanencia debe comenzar después del margen de salida.',true);const {error}=await db.from('company_settings').update(values).eq('id',1);if(error)return toast(error.message,true);toast('Reglas del motor actualizadas correctamente.');settings()}
async function requests(){const admin=state.profile.app_role==='admin';let q=db.from('requests').select('*,workers(full_name)').order('created_at',{ascending:false});if(!admin)q=q.eq('worker_id',state.profile.worker_id);const {data,error}=await q;if(error)throw error;$('#view').innerHTML=`<div class="section-head"><h2>${admin?'Solicitudes del personal':'Mis solicitudes'}</h2>${admin?'':'<button onclick="requestForm()">+ Nueva solicitud</button>'}</div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Trabajador</th><th>Tipo</th><th>Detalle</th><th>Estado</th><th></th></tr></thead><tbody>${(data||[]).map(x=>`<tr><td>${date(x.occurrence_date)}</td><td>${esc(x.workers?.full_name||'')}</td><td>${esc(x.type)}</td><td>${esc(x.detail)}</td><td><span class="badge ${x.status==='approved'?'ok':x.status==='rejected'?'danger':''}">${esc(statusLabel(x.status))}</span></td><td>${admin&&x.status==='pending'?`<div class="actions"><button onclick="resolveRequest(${x.id},'approved')">Aprobar</button><button class="danger-btn" onclick="resolveRequest(${x.id},'rejected')">Rechazar</button></div>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hay solicitudes.</td></tr>'}</tbody></table></div>`}
function requestForm(){modal(`<h2>Nueva solicitud</h2><form id="req"><label>Tipo<select name="type"><option>Permiso</option><option>Justificación de falta</option><option>Justificación de tardanza</option><option>Vacaciones</option></select></label><label>Fecha<input type="date" name="occurrence_date" required></label><label>Detalle<textarea name="detail" required></textarea></label><button>Enviar solicitud</button></form>`);$('#req').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.worker_id=state.profile.worker_id;const {error}=await db.from('requests').insert(o);if(error)return toast(error.message,true);$('#modal').remove();toast('Solicitud enviada.');requests()}}
async function resolveRequest(id,status){const note=prompt('Nota del administrador:')||'';const {error}=await db.from('requests').update({status,admin_note:note,reviewed_at:new Date().toISOString(),reviewed_by:state.session.user.id}).eq('id',id);toast(error?error.message:'Solicitud resuelta.',!!error);requests()}
